WITH recent_stores AS (SELECT * FROM stores WHERE store_name IS NOT NULL AND sqft < 16063), stores_stats AS (SELECT CASE WHEN sqft >= 14046 THEN 'high' WHEN sqft >= 4380 THEN 'mid' ELSE 'low' END sqft_bucket, MIN(sqft) min_sqft FROM recent_stores GROUP BY CASE WHEN sqft >= 14046 THEN 'high' WHEN sqft >= 4380 THEN 'mid' ELSE 'low' END) SELECT sqft_bucket, min_sqft FROM stores_stats
